<?php
namespace App\Services;
use App\Models\{Media,LocationShare};
use App\Support\{ApiResponse,RequestContext};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Storage;
use Illuminate\Support\Str;
class MediaService
{
 public function handle(string $op,Request $r){return match($op){
 'post_uploads_presign'=>$this->presign($r),'post_uploads_complete'=>$this->complete($r),'get_media_mediaid'=>$this->media($r),'delete_media_mediaid'=>$this->deleteMedia($r),
 'post_location_shares'=>$this->locationCreate($r),'get_location_shares_shareid'=>$this->locationGet($r),'patch_location_shares_shareid'=>$this->locationPatch($r),'delete_location_shares_shareid'=>$this->locationDelete($r),'get_location_shares_shareid_status'=>$this->locationStatus($r),default=>ApiResponse::problem('Unsupported media operation',$op,501,'not_implemented')};}
 private function presign(Request $r){$d=$r->validate(['filename'=>'required|string|max:255','mime'=>'required|string|max:150','size'=>'required|integer|min:1|max:1073741824']);$key='couples/'.RequestContext::coupleSpaceId($r).'/'.Str::uuid().'/'.preg_replace('/[^A-Za-z0-9._-]/','_',$d['filename']);$disk=Storage::disk(config('143.upload_disk'));try{$url=$disk->temporaryUploadUrl($key,now()->addMinutes(15),['ContentType'=>$d['mime']]);return ApiResponse::ok(['key'=>$key,'url'=>$url['url']??$url,'headers'=>$url['headers']??[],'expires_in'=>900]);}catch(\Throwable $e){return ApiResponse::ok(['key'=>$key,'direct_upload_required'=>true,'note'=>'Configured disk does not expose temporaryUploadUrl; use multipart backend upload adapter or S3-compatible driver.']);}}
 private function complete(Request $r){$d=$r->validate(['key'=>'required|string|max:1024','mime'=>'required|string|max:150','size'=>'required|integer|min:1','checksum'=>'nullable|string|max:128','metadata'=>'nullable|array']);$space=RequestContext::coupleSpaceId($r);$prefix='couples/'.$space.'/';if(!$space||!str_starts_with($d['key'],$prefix))return ApiResponse::problem('Invalid object key','The uploaded object does not belong to the current couple space.',403,'invalid_object_key');$disk=Storage::disk(config('143.upload_disk'));if(!$disk->exists($d['key']))return ApiResponse::problem('Upload not found','The object was not found in private storage.',422,'upload_not_found');$actual=$disk->size($d['key']);if((int)$actual!==(int)$d['size'])return ApiResponse::problem('Upload size mismatch','Uploaded object size does not match the declared size.',422,'upload_size_mismatch',['actual_size'=>$actual]);$m=Media::create(['couple_space_id'=>$space,'user_id'=>$r->user()->id,'storage_disk'=>config('143.upload_disk'),'storage_key'=>$d['key'],'mime'=>$d['mime'],'size'=>$actual,'checksum'=>$d['checksum']??null,'metadata'=>$d['metadata']??[]]);return ApiResponse::created($m);}
 private function media(Request $r){$m=Media::where('id',$r->route('mediaId'))->where('couple_space_id',RequestContext::coupleSpaceId($r))->firstOrFail();$url=Storage::disk($m->storage_disk)->temporaryUrl($m->storage_key,now()->addMinutes(10));return ApiResponse::ok(['media'=>$m,'url'=>$url,'expires_in'=>600]);}
 private function deleteMedia(Request $r){$m=Media::where('id',$r->route('mediaId'))->where('user_id',$r->user()->id)->firstOrFail();Storage::disk($m->storage_disk)->delete($m->storage_key);$m->delete();return ApiResponse::ok(['deleted'=>true]);}
 private function locationCreate(Request $r){$d=$r->validate(['mode'=>'required|in:single,live,until_arrival','latitude'=>'required|numeric|between:-90,90','longitude'=>'required|numeric|between:-180,180','expires_at'=>'nullable|date|after:now','destination'=>'nullable|array','metadata'=>'nullable|array']);$x=LocationShare::create(array_merge($d,['user_id'=>$r->user()->id,'couple_space_id'=>RequestContext::coupleSpaceId($r),'status'=>'active']));event(new \App\Events\DomainRealtimeEvent('location.updated',$x->toArray(),null,$x->couple_space_id));return ApiResponse::created($x);}
 private function loc(Request $r){return LocationShare::where('id',$r->route('shareId'))->where('couple_space_id',RequestContext::coupleSpaceId($r))->firstOrFail();}
 private function locationGet(Request $r){return ApiResponse::ok($this->loc($r));}
 private function locationPatch(Request $r){$x=$this->loc($r);if($x->user_id!==$r->user()->id)return ApiResponse::problem('Forbidden','Only the sharing user can update live location.',403,'forbidden');$d=$r->validate(['latitude'=>'required|numeric|between:-90,90','longitude'=>'required|numeric|between:-180,180']);$x->update($d);event(new \App\Events\DomainRealtimeEvent('location.updated',$x->toArray(),null,$x->couple_space_id));return ApiResponse::ok($x);}
 private function locationDelete(Request $r){$x=$this->loc($r);if($x->user_id!==$r->user()->id)return ApiResponse::problem('Forbidden','Only the sharing user can stop sharing.',403,'forbidden');$x->update(['status'=>'ended','ended_at'=>now()]);event(new \App\Events\DomainRealtimeEvent('location.share.ended',['id'=>$x->id],null,$x->couple_space_id));return ApiResponse::ok(['ended'=>true]);}
 private function locationStatus(Request $r){$x=$this->loc($r);return ApiResponse::ok(['status'=>$x->status,'expires_at'=>$x->expires_at,'ended_at'=>$x->ended_at]);}
}
